CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), role TEXT NOT NULL CHECK(role IN ('organizer','host')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS venues (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, name TEXT NOT NULL, city TEXT NOT NULL, locality TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('demo','research')), policy_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, venue_id TEXT NOT NULL REFERENCES venues(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('room','equipment')), quantity INTEGER NOT NULL CHECK(quantity > 0), capacity INTEGER, setup_minutes INTEGER NOT NULL DEFAULT 0, cleanup_minutes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS availability_windows (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, venue_id TEXT NOT NULL, resource_id TEXT, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, released INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS internal_blocks (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, venue_id TEXT NOT NULL, resource_id TEXT, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, venue_id TEXT NOT NULL, status TEXT NOT NULL, idempotency_key TEXT NOT NULL, payload_json TEXT NOT NULL, brief_json TEXT NOT NULL, accepted_brief_json TEXT, proposed_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS allocations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, application_id TEXT NOT NULL REFERENCES applications(id), resource_id TEXT NOT NULL REFERENCES resources(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('hold','reservation','released')), expires_at TEXT, quantity INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS checklist_items (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, application_id TEXT NOT NULL REFERENCES applications(id), label TEXT NOT NULL, owner TEXT NOT NULL, due_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, UNIQUE(application_id,label));
CREATE TABLE IF NOT EXISTS transition_history (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, application_id TEXT NOT NULL REFERENCES applications(id), actor TEXT NOT NULL, from_status TEXT, to_status TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS allocations_overlap ON allocations(workspace_id,resource_id,state,starts_at,ends_at);
CREATE INDEX IF NOT EXISTS applications_queue ON applications(workspace_id,venue_id,status,created_at);
